// =====================
// 1) CONFIG (puxa do node "Configuração do fluxo")
// =====================
const cfgItem = ($items("Configuração do fluxo")?.[0]?.json) ?? {};
const maxPrice = Number(cfgItem.maxPrice ?? 79.90);
const minPrice = Number(cfgItem.minPrice ?? 0);
const minScore = Number(cfgItem.minScore ?? 1);

// =====================
// 2) KEYWORDS (positivas e negativas)
// =====================
const POSITIVE_KEYWORDS = [
  "kit", "organizador", "suporte", "capa", "capinha", "pelicula", "película",
  "usb", "type c", "tipo c", "carregador", "cabo", "adaptador",
  "led", "luz", "lanterna", "sensor", "magnetico", "magnético", "ima", "imã",
  "portatil", "portátil", "dobravel", "dobrável", "recarregavel", "recarregável", "silicone",
  "cozinha", "casa", "decoracao", "decoração", "banheiro", "limpeza",
  "pet", "gato", "cachorro", "automotivo", "carro",
  "porta", "gancho", "ganchos", "cabide", "cabideiro", "prateleira",
  "caixa", "caixinha", "pote", "pote hermetico", "pote hermético", "recipiente",
  "cesto", "lixeira", "dispenser", "dispensador", "dosador", "borrifador", "pulverizador",
  "escova", "esponja", "toalha", "pano", "tapete", "capacho",
  "pelicula 3d", "película 3d", "suporte celular", "suporte carro", "fone", "fone bluetooth",
  "decorativo", "decorativa", "quadro", "placa", "plaquinha", "adesivo", "moldura", "enfeite",
  "necessaire", "nécessaire", "pente", "pinça", "lixa", "hidratante", "sabonete",
  "estojo", "caneta", "caderno", "material escolar",
  "camiseta", "camisa", "blusa", "cropped", "moletom", "jaqueta",
  "calca", "calça", "bermuda", "short", "vestido", "saia", "conjunto",
  "moda", "feminino", "masculino", "unissex", "casual", "basico", "básico", "inverno", "verao", "verão"
];

const NEGATIVE_KEYWORDS = [
  "emagrecedor", "capsulas", "cápsulas", "gotas", "original envio hoje", "green", "lepti",
  "curso", "ebook", "apostila", "assinatura",
  "casamento", "gravata", "urna", "pix", "alianca", "aliança", "porta alianca", "porta aliança"
];

function toNumber(v) {
  if (v === null || v === undefined) return NaN;
  const s = String(v).trim().replace(",", ".");
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
}

function norm(s) {
  return String(s ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function countMatches(text, list) {
  const hits = [];
  for (const kw of list) {
    const k = norm(kw);
    if (k && text.includes(k)) hits.push(kw);
  }
  return hits;
}

const root = $input.first()?.json ?? {};
if (root.errors?.length) return [];

const nodes = root?.data?.productOfferV2?.nodes ?? root?.products ?? [];
if (!Array.isArray(nodes) || nodes.length === 0) return [];

let offers = nodes.map(n => {
  const price = toNumber(n.price);
  return {
    productName: n.productName ?? n.title ?? "",
    offerLink: n.offerLink ?? n.link ?? "",
    productLink: n.productLink ?? n.url ?? "",
    imageUrl: n.imageUrl ?? n.image ?? "",
    price,
    commissionRate: toNumber(n.commissionRate ?? 0.2),
    commission: toNumber(n.commission ?? price * 0.2),
  };
});

offers = offers.filter(o =>
  Number.isFinite(o.price) &&
  o.price >= minPrice &&
  o.price <= maxPrice
);

offers = offers.map(o => {
  const name = norm(o.productName);
  const posHits = countMatches(name, POSITIVE_KEYWORDS);
  const negHits = countMatches(name, NEGATIVE_KEYWORDS);
  const score = (posHits.length * 1) - (negHits.length * 2);
  return { ...o, score, posHits, negHits };
});

offers = offers.filter(o => o.score >= minScore);

offers.sort((a, b) => {
  if (b.score !== a.score) return b.score - a.score;
  return a.price - b.price;
});

return offers.map(oferta => ({ json: { oferta } }));

// Filtrar Comissão
const cfg = $node["Configuração do fluxo"].json;
const minComission = Number(cfg.minComission ?? 1);
const minComissionRate = Number(cfg.minComissionRate ?? 0.1);

const items = $input.all();

return items.filter((it) => {
  const o = it.json.oferta || it.json;
  const commission = Number(o.commission ?? 0);
  const commissionRate = Number(o.commissionRate ?? 0);
  return commission >= minComission && commissionRate >= minComissionRate;
});

// Node: Diversificar (dedupe + limite por categoria)
const MAX_PER_CATEGORY = 3;

const LIMITED_CATEGORIES = new Set([
  "roupas", "oculos", "relogio", "livros", "capinhas", "peliculas"
]);

const CATEGORY_RULES = [
  {
    cat: "roupas",
    keys: ["camiseta","camisa","blusa","cropped","moletom","jaqueta","calca","calça","bermuda","short","vestido","saia","conjunto","moda","feminino","masculino","unissex","casual","basico","básico","inverno","verao","verão"],
  },
  {
    cat: "oculos",
    keys: ["oculos","óculos","lente","uv400","solar","armação","armacao"],
  },
  {
    cat: "relogio",
    keys: ["relogio","relógio","smartwatch","pulseira inteligente","watch"],
  },
  {
    cat: "livros",
    keys: ["livro","livros","ebook","e-book","romance","hq","manga","mangá","box"],
  },
  {
    cat: "capinhas",
    keys: ["capinha","capa case","capa","case","full cover","360"],
  },
  {
    cat: "peliculas",
    keys: ["pelicula","película","vidro","glass","protector","protetor de tela"],
  },
];

function norm(s) {
  return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^\p{L}\p{N}\s]+/gu, " ").replace(/\s+/g, " ").trim();
}

function detectCategory(productName) {
  const n = norm(productName);
  for (const rule of CATEGORY_RULES) {
    for (const k of rule.keys) {
      if (n.includes(norm(k))) return rule.cat;
    }
  }
  return "outros";
}

const itemsIn = $input.all();
itemsIn.sort((a, b) => {
  const A = a.json?.oferta || {};
  const B = b.json?.oferta || {};
  const sA = Number(A.score ?? 0);
  const sB = Number(B.score ?? 0);
  if (sB !== sA) return sB - sA;
  const cA = Number(A.commission ?? 0);
  const cB = Number(B.commission ?? 0);
  return cB - cA;
});

const seenNames = new Set();
const catCounts = new Map();
const out = [];

for (const item of itemsIn) {
  const oferta = item.json?.oferta;
  if (!oferta?.productName) continue;
  const nameKey = norm(oferta.productName);
  if (!nameKey || seenNames.has(nameKey)) continue;

  const cat = detectCategory(oferta.productName);
  oferta._categoria = cat;

  if (LIMITED_CATEGORIES.has(cat)) {
    const current = catCounts.get(cat) ?? 0;
    if (current >= MAX_PER_CATEGORY) continue;
    catCounts.set(cat, current + 1);
  }

  seenNames.add(nameKey);
  out.push({ json: { oferta } });
}

return out;

// Gera Copy Altamente Persuasiva e Formatada no Padrão do WhatsApp Garimpa Store
const o = $input.first().json.oferta || $input.first().json;

const titulo = o.productName || 'Achadinho Exclusivo';
const preco = Number(o.price) || 0;
const link = o.offerLink || o.productLink || '';
const imagem = o.imageUrl || '';

let linhas = [];
linhas.push(`🔥 **OFERTA IMPERDÍVEL SHOPEE!** 🛍️\n`);
linhas.push(`📦 **${titulo}**\n`);
linhas.push(`💵 **R$ ${preco.toFixed(2).replace('.', ',')}** ✨`);
linhas.push(`\n✅ Ideal para praticidade no dia a dia`);
linhas.push(`✅ Qualidade garantida e envio rápido`);
linhas.push(`\n👉 **GARANTA O SEU AGORA:**`);
linhas.push(`🔗 ${link}`);
linhas.push(`\n⏰ *Aproveite enquanto dura o estoque promocional!*`);

const copyFormatada = linhas.join('\n');

return [{
  json: {
    'Nome Produto': titulo,
    'Imagem Produto': imagem,
    'preco': preco,
    'link_produtos_afiliado': link,
    'titulo_produto': titulo,
    'mensagem': copyFormatada,
    'Plataforma': 'Shopee',
    'Status_Meta': 'Pendente'
  }
}];
